# Base Droid class
class Droid:
    def __init__(self, name, battery_level):
        self.name = name
        self.battery_level = battery_level

    def greet(self):
        print(f"Greetings. I am {self.name}, Worker Unit.")

# SecurityDroid inherits everything from Droid
class SecurityDroid(Droid):
    pass

# Test that inheritance works
guard = SecurityDroid('GUARD-X1', 100)
guard.greet()  # Inherited method works!

